'use strict';

// MAIN //

class Float16Array {
	constructor(input) {
		if (typeof input === 'number') {
			this._buffer = new Uint16Array(input);
		} else if (Array.isArray(input)) {
			this._buffer = new Uint16Array(input.length);
			for (let i = 0; i < input.length; i++) {
				this._buffer[i] = Float16Array.toFloat16(input[i]);
			}
		} else {
			throw new TypeError('Unsupported constructor argument');
		}
		this.length = this._buffer.length;
	}

	get(index) {
		return Float16Array.fromFloat16(this._buffer[index]);
	}

  get buffer() {
	return this._buffer.buffer;
  }

  get byteLength() {
	return this._buffer.byteLength;
  }

  get byteOffset() {
	return this._buffer.byteOffset;
  }

  get BYTES_PER_ELEMENT() {
    return 2;
  }

  get [Symbol.toStringTag]() {
  return 'Float16Array';
  }

  copyWithin(target, start, end) {
		target = target >> 0;
		start = start >> 0;
		end = end === undefined ? this.length : end >> 0;

		const to = target < 0 ? this.length + target : target;
		const from = start < 0 ? this.length + start : start;
		const final = end < 0 ? this.length + end : end;

		const count = Math.min(final - from, this.length - to);
		const direction = from < to && to < (from + count) ? -1 : 1;

		if (direction === -1) {
			for (let i = count - 1; i >= 0; i--) {
				this._buffer[to + i] = this._buffer[from + i];
			}
		} else {
			for (let i = 0; i < count; i++) {
				this._buffer[to + i] = this._buffer[from + i];
			}
		}
		return this;
	}

  set(indexOrArray, value) {
	if (typeof indexOrArray === 'number') {
		if (indexOrArray < 0 || indexOrArray >= this.length) {
			throw new RangeError('Index out of bounds');
		}
		this._buffer[indexOrArray] = Float16Array.toFloat16(value);
		return;
	}

	const source = indexOrArray;
	const offset = value !== undefined ? Number(value) : 0;

	if (offset < 0 || offset > this.length) {
		throw new RangeError('Offset is out of bounds');
	}

	if (
		(Array.isArray(source) ||
		(ArrayBuffer.isView(source) && typeof source.length === 'number') ||
		(source instanceof Float16Array))
	) {
		const len = Math.min(source.length, this.length - offset);
		for (let i = 0; i < len; i++) {
			const val = typeof source.get === 'function' ? source.get(i) : source[i];
			this._buffer[offset + i] = Float16Array.toFloat16(val);
		}
		return;
	}

	throw new TypeError('Invalid arguments for set');
  }

  entries() {
	return this._entriesGenerator();
}

*_entriesGenerator() {
	for (let i = 0; i < this.length; i++) {
		yield [i, this.get(i)];
	}
}

every(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}
	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (!callback.call(thisArg, value, i, this)) {
			return false;
		}
	}
	return true;
}

filter(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	const result = [];
	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			result.push(value);
		}
	}

	return new Float16Array(result);
}

findIndex(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			return i;
		}
	}
	return -1;
}

find(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			return value;
		}
	}
	return undefined;
}

forEach(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}
	for (let i = 0; i < this.length; i++) {
		callback.call(thisArg, this.get(i), i, this);
	}
}

static from(source, mapFn, thisArg) {
	if (source == null) {
		throw new TypeError('source cannot be null or undefined');
	}
	if (mapFn !== undefined && typeof mapFn !== 'function') {
		throw new TypeError('when provided, mapFn must be a function');
	}

	let values = [];
	const iteratorSymbol = typeof Symbol === 'function' && Symbol.iterator;

	if (iteratorSymbol && source[iteratorSymbol]) {
		const iterator = source[iteratorSymbol]();
		let step;
		while (!(step = iterator.next()).done) {
			values.push(step.value);
		}
	} else if (typeof source.length === 'number') {
		for (let i = 0; i < source.length; i++) {
			values.push(source[i]);
		}
	} else {
		throw new TypeError('source is not iterable or array-like');
	}

	if (mapFn) {
		if (thisArg) {
			values = values.map(function(v, i) {
				return mapFn.call(thisArg, v, i);
			});
		} else {
			values = values.map(mapFn);
		}
	}

	const arr = new Float16Array(values.length);
	for (let i = 0; i < values.length; i++) {
		arr.set(i, values[i]);
	}
	return arr;
}

includes(searchElement, fromIndex = 0) {
	if (fromIndex < 0) {
		fromIndex = Math.max(this.length + fromIndex, 0);
	}
	for (let i = fromIndex; i < this.length; i++) {
		if (this.get(i) === searchElement) {
			return true;
		}
	}
	return false;
}

indexOf(searchElement, fromIndex = 0) {
	fromIndex = Math.max(fromIndex >= 0 ? fromIndex : this.length + fromIndex, 0);
	for (let i = fromIndex; i < this.length; i++) {
		if (this.get(i) === searchElement) {
			return i;
		}
	}
	return -1;
}

join(separator = ',') {
	let result = '';
	for (let i = 0; i < this.length; i++) {
		if (i > 0) result += separator;
		result += String(this.get(i));
	}
	return result;
}

keys() {
	return this._keysGenerator();
}

*_keysGenerator() {
	for (let i = 0; i < this.length; i++) {
		yield i;
	}
}

lastIndexOf(searchElement, fromIndex) {
	let i = fromIndex !== undefined ? fromIndex : this.length - 1;
	if (i >= this.length) i = this.length - 1;
	if (i < 0) i = this.length + i;

	for (; i >= 0; i--) {
		if (Object.is(this.get(i), searchElement)) {
			return i;
		}
	}
	return -1;
}

map(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError(callback + ' is not a function');
	}

	const result = new this.constructor(this.length);

	for (let i = 0; i < this.length; i++) {
		if (Object.prototype.hasOwnProperty.call(this, i)) {
			const mappedValue = callback.call(thisArg, this.get(i), i, this);
			result.set(i, mappedValue);
		}
	}

	return result;
}

slice(start = 0, end = this.length) {
	const len = this.length;

	let relativeStart = start < 0 ? Math.max(len + start, 0) : Math.min(start, len);
	let relativeEnd = end < 0 ? Math.max(len + end, 0) : Math.min(end, len);

	const count = Math.max(relativeEnd - relativeStart, 0);
	const result = new this.constructor(count);

	for (let i = 0; i < count; i++) {
		result.set(i, this.get(relativeStart + i));
	}
	return result;
}

sort(compareFn) {
	const values = [];
	for (let i = 0; i < this.length; i++) {
		values.push(this.get(i));
	}

	values.sort((a, b) => {
		if (compareFn) return compareFn(a, b);
		if (a !== a) return 1;
		if (b !== b) return -1;
		return a - b;
	});

	for (let i = 0; i < this.length; i++) {
		this.set(i, values[i]);
	}
	return this;
}

values() {
	return this._valuesGenerator();
}

*_valuesGenerator() {
	for (let i = 0; i < this.length; i++) {
		yield this.get(i);
	}
}

some(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError(callback + ' is not a function');
	}
	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			return true;
		}
	}
	return false;
}

reduce(callback, initialValue) {
	const length = this.length;
	if (typeof callback !== 'function') {
		throw new TypeError(callback + ' is not a function');
	}

	let accumulator;
	let startIndex = 0;

	if (arguments.length >= 2) {
		accumulator = initialValue;
	} else {
		if (length === 0) {
			throw new TypeError('Reduce of empty array with no initial value');
		}
		accumulator = this.get(0);
		startIndex = 1;
	}

	for (let i = startIndex; i < length; i++) {
		accumulator = callback(accumulator, this.get(i), i, this);
	}

	return accumulator;
}

reduceRight(callback, initialValue) {
	const length = this.length;
	if (typeof callback !== 'function') {
		throw new TypeError(callback + ' is not a function');
	}

	let accumulator;
	let startIndex = length - 1;

	if (arguments.length >= 2) {
		accumulator = initialValue;
	} else {
		if (length === 0) {
			throw new TypeError('Reduce of empty array with no initial value');
		}
		accumulator = this.get(startIndex);
		startIndex--;
	}

	for (let i = startIndex; i >= 0; i--) {
		accumulator = callback(accumulator, this.get(i), i, this);
	}

	return accumulator;
}

subarray(begin = 0, end = this.length) {
	const len = this.length;

	let start = begin < 0 ? Math.max(len + begin, 0) : Math.min(begin, len);
	let finish = end < 0 ? Math.max(len + end, 0) : Math.min(end, len);

	start = Math.min(start, len);
	finish = Math.min(Math.max(finish, start), len);

	const count = Math.max(finish - start, 0);
	const SubArrayCtor = this.constructor;

	const result = new SubArrayCtor(count);

	for (let i = 0; i < count; i++) {
		result.set(i, this.get(start + i));
	}
	return result;
}

reverse() {
	const mid = Math.floor(this.length / 2);
	for (let i = 0; i < mid; i++) {
		const j = this.length - 1 - i;

		const temp = this._buffer[i];
		this._buffer[i] = this._buffer[j];
		this._buffer[j] = temp;
	}
	return this;
}

 fill(value, start = 0, end = this.length) {
	start = start < 0 ? Math.max(this.length + start, 0) : Math.min(start, this.length);
	end = end < 0 ? Math.max(this.length + end, 0) : Math.min(end, this.length);

	const bits = Float16Array.toFloat16(value);

	for (let i = start; i < end; i++) {
		this._buffer[i] = bits;

		Object.defineProperty(this, i, {
			get: () => this.get(i),
			set: (val) => this.set(i, val),
			enumerable: true,
			configurable: true
		});
	}
	return this;
}

  static of(...args) {
  const arr = new Float16Array(args.length);
  for (let i = 0; i < args.length; i++) {
    arr.set(i, args[i]);
  }
  return arr;
}

	static toFloat16(val) {
		const floatView = new Float32Array(1);
		const intView = new Uint32Array(floatView.buffer);

		floatView[0] = val;
		const x = intView[0];

		const sign = (x >> 16) & 0x8000;
		const exponent = ((x >> 23) & 0xff) - 127;
		const fraction = x & 0x7fffff;

		if (exponent <= -15) {
			if (exponent < -24) return sign;
			const sub = (fraction | 0x800000) >> (-exponent - 1);
			return sign | (sub >> 13);
		}

		if (exponent >= 16) {
			return sign | 0x7c00;
		}

		const exp = exponent + 15;
		const frac = fraction >> 13;
		return sign | (exp << 10) | frac;
	}

	static fromFloat16(bits) {
		const sign = (bits & 0x8000) << 16;
		let exponent = (bits & 0x7C00) >> 10;
		const fraction = bits & 0x03FF;

		let result;
		if (exponent === 0) {
			if (fraction === 0) {
				result = sign;
			} else {
				exponent = 1;
				while ((fraction & 0x0400) === 0) {
					fraction <<= 1;
					exponent--;
				}
				fraction &= ~0x0400;
				const exp32 = 127 - 15 - exponent;
				const frac32 = fraction << 13;
				result = sign | (exp32 << 23) | frac32;
			}
		} else if (exponent === 0x1F) {
			result = sign | 0x7F800000 | (fraction << 13);
		} else {
			const exp32 = exponent - 15 + 127;
			result = sign | (exp32 << 23) | (fraction << 13);
		}

		const intView = new Uint32Array(1);
		intView[0] = result;
		const floatView = new Float32Array(intView.buffer);
		return floatView[0];
	}
}


// EXPORTS //

module.exports = Float16Array;
